def apply_traces(segments):
    """FAULT_SEGMENTS listesini gercek izlerle guncelle."""
    for seg in segments:
        t = TRACES.get(seg["name"])
        if t:
            seg["coords"] = t["coords"]
            seg["splays"] = t["splays"]
            seg["trace_source"] = t["trace_source"]
        else:
            seg.setdefault("splays", [])
            seg.setdefault("trace_source", "şematik")
